// Tests for the quick symptom and medicine logs (src/quicklog.js). Run: npm test (Node 18+).
// Node has no DOM, so a very small stand-in document is built here: just what the two forms use.
// Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { symptomValue, medicineValue, amountText, logText, symptomLog, medicineLog, PRIVATE_NOTE, kitFindings, kitFindingText, kitFindingShort, KIT_HOURS } from '../src/quicklog.js';
import { CELLS } from '../src/config.js';

// ---------- a stand-in document ----------
class FakeNode {
  constructor(doc) { this.ownerDocument = doc; this.parentNode = null; this.childNodes = []; }
  get nextSibling() {
    if (!this.parentNode) return null;
    const list = this.parentNode.childNodes;
    return list[list.indexOf(this) + 1] || null;
  }
  get textContent() { return this.childNodes.map((c) => c.textContent).join(''); }
  set textContent(t) { this.replaceChildren(...(t === '' ? [] : [this.ownerDocument.createTextNode(String(t))])); }
  append(...nodes) { for (const n of nodes) this.insertBefore(n, null); }
  replaceChildren(...nodes) {
    for (const c of this.childNodes) c.parentNode = null;
    this.childNodes = [];
    this.append(...nodes);
  }
  insertBefore(node, ref) {
    if (ref === node) throw new Error('a node cannot be inserted before itself here');
    if (node.parentNode) node.parentNode.childNodes.splice(node.parentNode.childNodes.indexOf(node), 1);
    const i = ref ? this.childNodes.indexOf(ref) : -1;
    if (ref && i < 0) throw new Error('the reference node is not a child');
    if (i < 0) this.childNodes.push(node);
    else this.childNodes.splice(i, 0, node);
    node.parentNode = this;
    return node;
  }
}
class FakeText extends FakeNode {
  constructor(doc, text) { super(doc); this.data = String(text); }
  get textContent() { return this.data; }
  set textContent(t) { this.data = String(t); }
}
class FakeElement extends FakeNode {
  constructor(doc, tag) { super(doc); this.tagName = tag.toUpperCase(); this.attrs = new Map(); this.listeners = {}; this.hidden = false; this.value = ''; this.className = ''; }
  setAttribute(k, v) { this.attrs.set(k, String(v)); }
  getAttribute(k) { return this.attrs.has(k) ? this.attrs.get(k) : null; }
  addEventListener(type, fn) { (this.listeners[type] = this.listeners[type] || []).push(fn); }
  async fire(type) { for (const fn of this.listeners[type] || []) await fn({ type, target: this, preventDefault() {} }); }
}
class FakeDocument {
  createElement(tag) { return new FakeElement(this, tag); }
  createTextNode(text) { return new FakeText(this, text); }
}

const host = () => new FakeDocument().createElement('div');
const elements = (root) => [root, ...root.childNodes.filter((c) => c instanceof FakeElement).flatMap(elements)];
const buttons = (root) => elements(root).filter((e) => e.tagName === 'BUTTON');
const visible = (e) => { for (let n = e; n; n = n.parentNode) if (n.hidden) return false; return true; };
const button = (root, text) => {
  const b = buttons(root).find((x) => x.textContent === text && visible(x));
  assert.ok(b, `a visible button "${text}"`);
  return b;
};
const statusOf = (root) => elements(root).find((e) => e.getAttribute('role') === 'status').textContent;
const pressed = (root) => buttons(root).filter((b) => b.getAttribute('aria-pressed') === 'true').map((b) => b.textContent);
const NOW = new Date('2026-11-15T08:00:00Z');
const now = () => NOW;

// ---------- checking and wording ----------
test('a symptom entry: a symptom from the list and a whole number from 0 to 10, a short note', () => {
  assert.deepEqual(symptomValue({ symptom: 'headache', severity: 4 }), { symptom: 'headache', severity: 4 });
  assert.deepEqual(symptomValue({ symptom: 'backPain', severity: 0, note: '  after ARED  ' }), { symptom: 'backPain', severity: 0, note: 'after ARED' });
  assert.equal(symptomValue({ symptom: 'headache', severity: 11 }), null);
  assert.equal(symptomValue({ symptom: 'headache', severity: -1 }), null);
  assert.equal(symptomValue({ symptom: 'headache', severity: 4.5 }), null);
  assert.equal(symptomValue({ symptom: 'headache', severity: '4' }), null, 'a string is not a rating');
  assert.equal(symptomValue({ symptom: 'headache', severity: null }), null, 'null must never become 0');
  assert.equal(symptomValue({ symptom: 'toothache', severity: 3 }), null);
  assert.equal(symptomValue({ symptom: 'other', severity: 3 }), null, '"Something else" needs a few words');
  assert.deepEqual(symptomValue({ symptom: 'other', severity: 3, note: 'sore throat' }), { symptom: 'other', severity: 3, note: 'sore throat' });
  assert.equal(symptomValue({ symptom: 'skin', severity: 2, note: 'x'.repeat(500) }).note.length, 200);
  for (const v of [null, undefined, 'headache', 4, []]) assert.equal(symptomValue(v), null);
});

test('a medicine entry: a kit medicine takes its name, strength and unit from the kit list; another one needs a name', () => {
  assert.deepEqual(medicineValue({ medicine: 'melatonin', amount: 1, name: 'ignored' }), { medicine: 'melatonin', name: 'Melatonin', strength: '3 mg', amount: 1, unit: 'tablet' });
  assert.deepEqual(medicineValue({ medicine: 'zolpidem', amount: 0.5 }), { medicine: 'zolpidem', name: 'Zolpidem', strength: '10 mg', amount: 0.5, unit: 'tablet' });
  assert.deepEqual(medicineValue({ medicine: 'other', amount: 1, name: ' Eye drops ' }), { medicine: 'other', name: 'Eye drops', amount: 1, unit: 'dose' });
  assert.equal(medicineValue({ medicine: 'other', amount: 1, name: '  ' }), null);
  assert.equal(medicineValue({ medicine: 'aspirin-x', amount: 1 }), null);
  for (const amount of [0, -1, 11, NaN, '1', null]) assert.equal(medicineValue({ medicine: 'melatonin', amount }), null, String(amount));
});

test('when a medicine was taken: a real time, never in the future', () => {
  const twoHoursAgo = new Date(NOW.getTime() - 2 * 3600e3).toISOString();
  assert.equal(medicineValue({ medicine: 'ibuprofen', amount: 1, takenAt: twoHoursAgo }, { now: NOW }).takenAt, twoHoursAgo);
  assert.equal(medicineValue({ medicine: 'ibuprofen', amount: 1, takenAt: '2026-11-15T09:00:00Z' }, { now: NOW }), null);
  assert.equal(medicineValue({ medicine: 'ibuprofen', amount: 1, takenAt: 'yesterday' }, { now: NOW }), null);
  assert.equal(medicineValue({ medicine: 'ibuprofen', amount: 1, takenAt: {} }, { now: NOW }), null);
});

test('plain lines for the screen and the doctor', () => {
  assert.equal(amountText(0.5, 'tablet'), 'half a tablet');
  assert.equal(amountText(1, 'tablet'), '1 tablet');
  assert.equal(amountText(2, 'tablet'), '2 tablets');
  assert.equal(logText('symptoms', { symptom: 'headache', severity: 4 }), 'Headache, 4 of 10');
  assert.equal(logText('symptoms', { symptom: 'other', severity: 3, note: 'sore throat' }), 'Something else, 3 of 10: sore throat');
  assert.equal(logText('medicines', { medicine: 'melatonin', name: 'Melatonin', strength: '3 mg', amount: 1, unit: 'tablet' }), 'Melatonin 3 mg, 1 tablet');
  assert.equal(logText('medicines', { medicine: 'ibuprofen', name: 'Ibuprofen', strength: '400 mg', amount: 2, unit: 'tablet', takenAt: '2026-11-14T22:10:00Z' }), 'Ibuprofen 400 mg, 2 tablets, taken GMT 318/22:10');
  assert.equal(logText('visionCheck', 'no change'), 'No change: I see as before, and all grid lines look straight');
  assert.equal(logText('pulse', 72), null, 'other measures are left to the screen');
  assert.equal(logText('symptoms', 'junk'), 'Unreadable symptom entry');
  assert.equal(logText('symptoms', { symptom: 'headache' }), 'Unreadable symptom entry', 'never "undefined of 10"');
  assert.equal(logText('medicines', { medicine: 'melatonin', name: 'Melatonin', strength: '3 mg' }), 'Unreadable medicine entry', 'never "undefined tablets"');
});

// ---------- the symptom form ----------
test('symptom log: pick a symptom, a number, save: about ten seconds and three taps', async () => {
  const saved = [];
  const h = host();
  symptomLog(h, { onSave: (e) => { saved.push(e); }, now });
  await button(h, 'Headache').fire('click');
  await button(h, '4').fire('click');
  assert.deepEqual(pressed(h), ['Headache', '4']);
  await h.childNodes[0].fire('submit');
  assert.deepEqual(saved, [{ indicator: 'symptoms', value: { symptom: 'headache', severity: 4 }, time: NOW.toISOString() }]);
  assert.equal(statusOf(h), 'Saved: Headache, 4 of 10.');
  assert.deepEqual(pressed(h), [], 'the form is ready for the next entry');
});

test('symptom log: nothing is saved until both a symptom and a number are chosen; "Something else" needs words', async () => {
  const saved = [];
  const h = host();
  symptomLog(h, { onSave: (e) => saved.push(e), now });
  const form = h.childNodes[0];
  await form.fire('submit');
  assert.equal(saved.length, 0);
  assert.equal(statusOf(h), 'Choose what you feel and how strong it is.');
  await button(h, 'Something else').fire('click');
  await button(h, '3').fire('click');
  await form.fire('submit');
  assert.equal(saved.length, 0);
  assert.equal(statusOf(h), 'Write a few words about it.');
  elements(h).find((e) => e.tagName === 'INPUT').value = 'sore throat';
  await form.fire('submit');
  assert.deepEqual(saved.map((e) => e.value), [{ symptom: 'other', severity: 3, note: 'sore throat' }]);
});

test('symptom log: a second tap takes a choice back; a failed save keeps the choice', async () => {
  const h = host();
  let fail = true;
  const saved = [];
  symptomLog(h, { onSave: async (e) => { if (fail) throw new Error('offline'); saved.push(e); }, now });
  await button(h, 'Back pain').fire('click');
  await button(h, 'Back pain').fire('click');
  assert.deepEqual(pressed(h), []);
  await button(h, 'Back pain').fire('click');
  await button(h, '6').fire('click');
  await h.childNodes[0].fire('submit');
  assert.equal(statusOf(h), 'Could not save. Your choice is kept: try again.');
  assert.deepEqual(pressed(h), ['Back pain', '6']);
  fail = false;
  await h.childNodes[0].fire('submit');
  assert.equal(saved.length, 1);
});

test('symptom log: the 0 to 10 scale is complete, and the list is the one in the Symptoms cell', () => {
  const h = host();
  symptomLog(h, { onSave: () => {} });
  const labels = buttons(h).map((b) => b.textContent);
  for (let n = 0; n <= 10; n += 1) assert.ok(labels.includes(String(n)), String(n));
  const cell = CELLS.find((c) => c.indicator === 'symptoms');
  for (const s of cell.symptoms) assert.ok(labels.includes(s.label), s.label);
  assert.ok(elements(h).some((e) => e.textContent === PRIVATE_NOTE), 'says that it is private');
});

