// ---------- the rules the forms keep ----------
test('the forms use only the screen\'s own classes, no colour that carries meaning, and large targets', () => {
  const allowed = new Set(['questions', 'quicklog', 'q', 'q-label', 'chips', 'seg', 'custom', 'actions', 'btn', 'primary', 'secondary', 'note', 'ql-note', 'ql-name']);
  for (const build of [symptomLog, medicineLog]) {
    const h = host();
    build(h, { onSave: () => {}, onCancel: () => {} });
    for (const e of elements(h)) for (const c of e.className.split(' ').filter(Boolean)) assert.ok(allowed.has(c), `${build.name}: class ${c}`);
    for (const b of buttons(h)) {
      let big = /\bbtn\b/.test(b.className);
      for (let n = b.parentNode; n && !big; n = n.parentNode) big = /\bseg\b/.test(n.className);
      assert.ok(big, `${build.name}: "${b.textContent}" is in a .seg or is a .btn (48 px on the screen)`);
    }
  }
});

test('a form without onSave is a mistake the lead sees at once', () => {
  assert.throws(() => symptomLog(host(), {}), TypeError);
  assert.throws(() => medicineLog(host(), {}), TypeError);
});

// ---------- the kit list's own rules (final review of 15 Nov 2026) ----------
const dose = (medicine, amount, hoursAgo, extra = {}) => ({ time: new Date(NOW.getTime() - hoursAgo * 3600e3), value: medicineValue({ medicine, amount, name: 'Eye drops', ...extra }, { now: NOW }) });

test("kitFindings: more tablets every 24 hours than the kit list's limit", () => {
  assert.deepEqual(kitFindings([], { now: NOW }), []);
  assert.deepEqual(kitFindings(undefined, { now: NOW }), []);
  const ten = kitFindings([5, 4, 3, 2, 1].map((h) => dose('ibuprofen', 2, h)), { now: NOW });
  assert.deepEqual(ten, [{ rule: 'max', medicine: 'ibuprofen', total: 10, max: 8, unit: 'tablet', note: 'No more than 8 tablets every 24 hours. Take with food.', time: new Date(NOW.getTime() - 3600e3).toISOString() }]);
  assert.equal(kitFindingText(ten[0]), 'Ibuprofen 400 mg: 10 tablets in the last 24 hours. The kit list says: "No more than 8 tablets every 24 hours. Take with food."');
  assert.equal(kitFindingShort(ten[0]), "Ibuprofen: 10 tablets in 24 hours, more than the kit list's 8");
  assert.deepEqual(kitFindings([4, 3, 2, 1].map((h) => dose('ibuprofen', 2, h)), { now: NOW }), [], 'no more than 8: 8 is allowed');
  assert.deepEqual(kitFindings([KIT_HOURS + 1, 4, 3, 2, 1].map((h) => dose('ibuprofen', 2, h)), { now: NOW }), [], 'a dose of yesterday no longer counts');
  assert.deepEqual(kitFindings([3, 2, 1].map((h) => dose('acetaminophen', 4, h)), { now: NOW }), [], '12 tablets of acetaminophen is its limit');
  assert.equal(kitFindings([3, 2, 1, 0.5].map((h) => dose('acetaminophen', h === 0.5 ? 0.5 : 4, h)), { now: NOW })[0].total, 12.5);
  // takenAt, when given, is when the medicine was taken.
  const late = dose('ibuprofen', 2, 0, { takenAt: new Date(NOW.getTime() - 30 * 3600e3).toISOString() });
  assert.deepEqual(kitFindings([late, ...[4, 3, 2, 1].map((h) => dose('ibuprofen', 2, h))], { now: NOW }), []);
});

test('kitFindings: a sleep medicine with another one, or with one whose note says not with sleep meds, in one night', () => {
  const pair = kitFindings([dose('zolpidem', 1, 3), dose('promethazine', 1, 2)], { now: NOW, nightHours: 12 });
  assert.deepEqual(pair.map((f) => [f.rule, f.medicines, f.hours, f.notes.map((n) => n.medicine)]), [['night', ['zolpidem', 'promethazine'], 12, ['zolpidem', 'promethazine']]]);
  assert.equal(pair[0].time, new Date(NOW.getTime() - 2 * 3600e3).toISOString());
  assert.equal(kitFindingText(pair[0]), 'Zolpidem 10 mg (GMT 319/05:00) and Promethazine 25 mg (GMT 319/06:00), within 12 hours of each other. The kit list says of Zolpidem: "Do not use with other sleep meds." Of Promethazine: "May cause sedation and impair performance. Do not use with sleep meds."');
  assert.equal(kitFindingShort(pair[0]), 'Zolpidem with Promethazine: the kit list says not together');
  const sleep = kitFindings([dose('melatonin', 1, 3), dose('zolpidem', 0.5, 2)], { now: NOW });
  assert.equal(kitFindingText(sleep[0]), 'Melatonin 3 mg (GMT 319/05:00) and Zolpidem 10 mg (GMT 319/06:00), within 12 hours of each other. The kit list says: "Do not use with other sleep meds."');
  assert.equal(kitFindings([dose('meclizine', 1, 3), dose('melatonin', 1, 2)], { now: NOW })[0].notes.length, 2);
  for (const [list, why] of [
    [[dose('promethazine', 1, 3), dose('meclizine', 1, 2)], 'neither is a sleep medicine'],
    [[dose('zolpidem', 0.5, 5), dose('zolpidem', 0.5, 1)], 'the same medicine twice'],
    [[dose('zolpidem', 1, 15), dose('promethazine', 1, 2)], 'more than 12 hours apart'],
    [[dose('zolpidem', 1, 40), dose('promethazine', 1, 30)], 'both longer ago than 24 hours'],
    [[dose('melatonin', 1, 2), dose('other', 1, 1), dose('loratadine', 1, 1)], 'no rule for these'],
  ]) assert.deepEqual(kitFindings(list, { now: NOW }), [], why);
  assert.equal(kitFindings([dose('zolpidem', 1, 15), dose('promethazine', 1, 2)], { now: NOW, nightHours: 14 }).length, 1, 'nightHours is the draft passed in');
  // The newest pair only, newest finding first.
  const nights = kitFindings([dose('melatonin', 1, 30), dose('zolpidem', 1, 29), dose('melatonin', 1, 6), dose('zolpidem', 1, 5), ...[4, 3, 2, 1, 0.5].map((h) => dose('ibuprofen', 2, h))], { now: NOW });
  assert.deepEqual(nights.map((f) => f.rule), ['max', 'night']);
  assert.deepEqual(nights[1].times, [new Date(NOW.getTime() - 6 * 3600e3).toISOString(), new Date(NOW.getTime() - 5 * 3600e3).toISOString()]);
});

test('kitFindings reads only the structured fields: the kit notes are quoted, never parsed', () => {
  const cell = structuredClone(CELLS.find((c) => c.indicator === 'medicines'));
  for (const k of cell.kit) k.kitNote = 'Changed note.';
  const list = [5, 4, 3, 2, 1].map((h) => dose('ibuprofen', 2, h));
  const found = kitFindings(list, { now: NOW, cell });
  assert.equal(found[0].max, 8);
  assert.equal(found[0].note, 'Changed note.');
  cell.kit.find((k) => k.key === 'ibuprofen').max24h = 10;
  assert.deepEqual(kitFindings(list, { now: NOW, cell }), []);
  for (const bad of [null, {}, { time: NOW }, { time: NOW, value: 'ibuprofen' }, { time: 'yesterday', value: { medicine: 'ibuprofen', amount: 9 } }, { time: NOW, value: { medicine: 'ibuprofen', amount: -9 } }]) {
    assert.deepEqual(kitFindings([bad], { now: NOW }), [], JSON.stringify(bad));
  }
});

